-- Planning of a short-circuit function visits each node of a shared expression DAG once, also the nodes that are not executed lazily.
SELECT if(x < 0, a30, toUInt64(0)) AS result FROM (SELECT x, a29 + a29 AS a30 FROM (SELECT x, a28 + a28 AS a29 FROM (SELECT x, a27 + a27 AS a28 FROM (SELECT x, a26 + a26 AS a27 FROM (SELECT x, a25 + a25 AS a26 FROM (SELECT x, a24 + a24 AS a25 FROM (SELECT x, a23 + a23 AS a24 FROM (SELECT x, a22 + a22 AS a23 FROM (SELECT x, a21 + a21 AS a22 FROM (SELECT x, a20 + a20 AS a21 FROM (SELECT x, a19 + a19 AS a20 FROM (SELECT x, a18 + a18 AS a19 FROM (SELECT x, a17 + a17 AS a18 FROM (SELECT x, a16 + a16 AS a17 FROM (SELECT x, a15 + a15 AS a16 FROM (SELECT x, a14 + a14 AS a15 FROM (SELECT x, a13 + a13 AS a14 FROM (SELECT x, a12 + a12 AS a13 FROM (SELECT x, a11 + a11 AS a12 FROM (SELECT x, a10 + a10 AS a11 FROM (SELECT x, a9 + a9 AS a10 FROM (SELECT x, a8 + a8 AS a9 FROM (SELECT x, a7 + a7 AS a8 FROM (SELECT x, a6 + a6 AS a7 FROM (SELECT x, a5 + a5 AS a6 FROM (SELECT x, a4 + a4 AS a5 FROM (SELECT x, a3 + a3 AS a4 FROM (SELECT x, a2 + a2 AS a3 FROM (SELECT x, a1 + a1 AS a2 FROM (SELECT x, a0 + a0 AS a1 FROM (SELECT number AS x, number AS a0 FROM numbers(1)))))))))))))))))))))))))))))))) SETTINGS compile_expressions = 0, short_circuit_function_evaluation = 'enable';

-- A node shared by two lazily executed arguments is still executed lazily in both of them.
SELECT if(x = 0, 0, (s + 1) * (s + 2)) FROM (SELECT number AS x, intDiv(1, number) AS s FROM numbers(3)) ORDER BY x
SETTINGS short_circuit_function_evaluation = 'enable';
